    /\ rw_cells bsegs m' (bv_unsigned sp + -32) [C8 s2; C8 s1; C8 s0; C8 ra]
    /\ rw_cells bsegs m' stb (SpcHdrCells (mkSPC AVP_SPCI_STATE 0 w 1) j7)
