Definition scs_segB_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (stb u lo : Z) (j7 : list byte) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m',
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (Z_to_bv 64 stb) (Z_to_bv 64 312) a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (Z_to_bv 64 AOPDEL2) fc None m' (seg_rom bsegs)
    /\ munch [(lo, bv_unsigned sp); (stb, stb + 32)]%Z m m' /\ wmono bsegs m m' /\ mem_inv bsegs m'
    /\ stk bsegs m' lo (bv_unsigned sp)
    /\ rw_cells bsegs m' stb (SpcHdrCells (mkSPC AVP_SPCI_STATE u 0 0) j7)
    /\ ACONST m'.
Scheme kc__4 := Elimination for Corelib.Init.Logic.or Sort Prop.

Lemma scs_segB : forall (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (pcv rax t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 : word) (m : mem) (stb u lo : Z) (j7 dj : list byte),
  (pcv = Z_to_bv 64 ASCS_DISP_RET \/ pcv = ret_pc (Z_to_bv 64 ASCS_DISP_RET)) ->
  rw_cells bsegs m (bv_unsigned sp + -64) [CB 8 dj; C8 (Z_to_bv 64 2147450880); C8 (Z_to_bv 64 stb); C8 (Z_to_bv 64 ASCS_REL_RET)] ->
  rw_cells bsegs m (bv_unsigned sp + -32) [C8 s2; C8 s1; C8 s0; C8 ra] ->
  rw_cells bsegs m stb (SpcHdrCells (mkSPC AVP_SPCI_STATE u 1 1) j7) -> 0 <= u < 2^31 ->
  aapp stb SZ_SPCI_STATE -> stb mod 16 = 0 -> addressable m stb SZ_SPCI_STATE ->
  AXStatics2 m ->
  stk bsegs m lo (bv_unsigned sp + -64) -> lo + 64 <= bv_unsigned sp -> aceil <= lo ->
  mem_inv bsegs m -> ACONST m ->
  evt bsegs (scs_segB_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc stb u lo j7 m)
    (MS (mkR rax (Z_to_bv 64 (bv_unsigned sp + -64)) gp tp t0 t1 t2 (Z_to_bv 64 (stb + 24)) (Z_to_bv 64 (Z.shiftr (stb + 24) 3 + 2147450880))
             a0 a1 a2 a3 a4 a5 a6 a7 (Z_to_bv 64 (Z.shiftr stb 3 + 2147450880)) s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
